cases.rules:
rules:
  - name: meeting-notes
    match: {from: [notes@meetings.example]}
    actions: {label: Meeting Notes, archive: true}
  - name: dev-failures
    match:
      from: [ci@build.example]
      subject: [Failed, with issues]
    actions: {label: Dev Alerts, star: true, important: true}
  - name: dev-noise
    match:
      from: [ci@build.example]
      exclude: subject:failed
    actions: {label: Dev Alerts, archive: true, mark_read: true}
  - name: stale-alerts
    match: {query: "label:Alerts"}
    older_than: 7d
    actions: {archive: true}
  - name: newsletters
    match:
      from: [news@a.example, "\"Big Co\" <x@b.example>", café@c.example]
      to: [me+news@x.example, list team@y.example]
      query: has:attachment
    actions: {label: "Reading/News  Weekly", important: false, trash: true}
    note: "a <note> & \"quotes\""
  - name: quiet
    match: {to: [quiet@x.example]}
    actions: {mark_read: true}

