function triage() {
  const started = Date.now();
  const deadline = started + BUDGET_MS;
  const secs = () => Math.round((Date.now() - started) / 1000) + 's';
  const labels = {};
  const fast = typeof Gmail !== 'undefined';
  const ids = fast ? labelIds_() : {};
  const mode = fast ? 'Gmail API, up to 1000 per call' : 'GmailApp, 100 per call: add the Gmail service for speed';
  console.log(`triage ${VERSION}: ${STEPS.length} rules, ${mode}, stops after ${BUDGET_MS / 60000} min`);
  for (const [i, step] of STEPS.entries()) {
    const label = step.label ? ensureLabel_(labels, step.label) : null;
    let result = null;
    if (fast && !step.trash) {
      if (step.label && !ids[step.label]) Object.assign(ids, labelIds_());
      try {
        result = fastStep_(step, step.label ? ids[step.label] : null, deadline, secs);
      } catch (e) {
        console.log(`  ${step.rule}: Gmail API refused (${e.message}); using the slow path`);
      }
    }
    if (!result) result = slowStep_(step, label, deadline, secs);
    const note = result.skipped ? `, ${result.skipped} skipped` : result.done ? '' : ' (nothing to do)';
    console.log(`[${i + 1}/${STEPS.length}] ${step.rule}: ${result.done} ${result.unit}${note}`);
    if (Date.now() >= deadline) {
      const left = STEPS.slice(i).map((s) => s.rule).join(', ');
      console.log(`Time budget used after ${secs()}. Not finished: ${left}. Run again to continue.`);
      return false;
    }
  }
  console.log(`All rules up to date (${secs()}).`);
  return true;
