// Fast path: list matching message IDs and change them with batchModify, 1000 per call.
// Messages, not threads, as Gmail filters do: a person's reply in the same thread is untouched.
function fastStep_(step, labelId, deadline, secs) {
  const add = [labelId, step.star ? 'STARRED' : null, step.important === true ? 'IMPORTANT' : null];
  const remove = [step.archive ? 'INBOX' : null, step.mark_read ? 'UNREAD' : null,
    step.important === false ? 'IMPORTANT' : null];
  add.splice(0, add.length, ...add.filter(Boolean));
  remove.splice(0, remove.length, ...remove.filter(Boolean));
  const handled = new Set();
  let done = 0;
  let pageToken;
  while (Date.now() < deadline) {
    const page = Gmail.Users.Messages.list('me', { q: step.query, maxResults: 500, pageToken });
    const ids = (page.messages || []).map((m) => m.id).filter((id) => !handled.has(id));
    if (ids.length === 0) {
      // Every sweep query excludes finished mail, so a page of handled IDs means no progress.
      if (!page.nextPageToken) break;
      pageToken = page.nextPageToken;
      continue;
    }
    Gmail.Users.Messages.batchModify({ ids, addLabelIds: add, removeLabelIds: remove }, 'me');
    ids.forEach((id) => handled.add(id));
    done += ids.length;
    pageToken = undefined; // changed mail drops out of the query, so start again from the top
    console.log(`  ${step.rule}: +${ids.length} (${done} so far, ${secs()})`);
  }
  return { done, skipped: 0, unit: 'messages' };
}

// Slow path: GmailApp, 100 threads per call. Used without the Gmail service, for trash, or
// when the API refuses a rule.
function slowStep_(step, label, deadline, secs) {
  let done = 0;
  const skipped = new Set();
  const handled = new Set();
  while (Date.now() < deadline) {
    // Threads Gmail refused stay matched, so page past them rather than re-fetching them.
    const found = GmailApp.search(step.query, skipped.size, BATCH);
    const threads = found.filter((t) => !skipped.has(t.getId()));
    // Every sweep query excludes finished threads; seeing them again means no progress.
    if (threads.length === 0 || threads.every((t) => handled.has(t.getId()))) break;
    const refused = apply_(step, label, threads);
    refused.forEach((id) => skipped.add(id));
    threads.forEach((t) => handled.add(t.getId()));
    done += threads.length - refused.length;
    console.log(`  ${step.rule}: +${threads.length - refused.length} (${done} so far, ${secs()})`);
    if (found.length < BATCH && refused.length === threads.length) break;
  }
  return { done, skipped: skipped.size, unit: 'threads' };
}

function labelIds_() {
  const ids = {};
  (Gmail.Users.Labels.list('me').labels || []).forEach((l) => { ids[l.name] = l.id; });
  return ids;
}

// Apply a step to a batch. Gmail rejects a whole batch if any one thread cannot be
// changed ("Gmail operation not allowed"), so on failure retry thread by thread and
// return the IDs that still fail, logging enough to find them.
function apply_(step, label, threads) {
  const act = (ts) => {
    if (label) label.addToThreads(ts);
    if (step.star) ts.forEach((t) => t.getMessages().forEach((m) => m.star()));
    if (step.mark_read) GmailApp.markThreadsRead(ts);
    if (step.important === true) GmailApp.markThreadsImportant(ts);
    if (step.important === false) GmailApp.markThreadsUnimportant(ts);
    if (step.trash) GmailApp.moveThreadsToTrash(ts);
    else if (step.archive) GmailApp.moveThreadsToArchive(ts);
  };
  try {
    act(threads);
    return [];
  } catch (e) {
    console.log(`  ${step.rule}: batch refused (${e.message}); retrying one at a time`);
  }
  const refused = [];
  for (const t of threads) {
    try {
      act([t]);
    } catch (e) {
      refused.push(t.getId());
      console.log(`  skipped "${t.getFirstMessageSubject()}" ${t.getPermalink()} - ${e.message}`);
    }
  }
  return refused;
}

function dryRun() {
  for (const step of STEPS) {
    let count = 0;
    while (count < COUNT_CAP) {
      const page = GmailApp.search(step.query, count, 500).length;
      count += page;
      if (page < 500) break;
    }
    console.log(`${step.rule}: ${count >= COUNT_CAP ? COUNT_CAP + '+' : count} threads  [${step.query}]`);
  }
}

function syncFilters() {
  if (typeof Gmail === 'undefined') {
    throw new Error('Add the Gmail API service first: Services (+) → Gmail API → Add.');
  }
  const props = PropertiesService.getUserProperties();
  const managed = JSON.parse(props.getProperty('managedFilterIds') || '[]');
  const existing = new Set((Gmail.Users.Settings.Filters.list('me').filter || []).map((f) => f.id));
  for (const id of managed) {
    if (existing.has(id)) Gmail.Users.Settings.Filters.remove('me', id);
  }
  const cache = {};
  FILTERS.forEach((f) => { if (f.label) ensureLabel_(cache, f.label); });
  const ids = labelIds_();
  const created = [];
  for (const f of FILTERS) {
    const criteria = {};
    if (f.sender) criteria.from = f.sender;
    if (f.to) criteria.to = f.to;
    if (f.subject) criteria.subject = f.subject;
    if (f.query) criteria.query = f.query;
    if (f.negated_query) criteria.negatedQuery = f.negated_query;
    const add = f.label ? [ids[f.label], ...f.add] : [...f.add];
    const action = {};
    if (add.length) action.addLabelIds = add;
    if (f.remove.length) action.removeLabelIds = [...f.remove];
    try {
      created.push(Gmail.Users.Settings.Filters.create({ criteria, action }, 'me').id);
      console.log(`${f.rule}: filter created`);
    } catch (e) {
      console.log(`${f.rule}: NOT created - ${e.message}`);
    }
  }
  props.setProperty('managedFilterIds', JSON.stringify(created));
  console.log(`${created.length}/${FILTERS.length} filters in place.`);
  return FILTERS.length - created.length;
}

function installTrigger() {
  removeTrigger();
  ScriptApp.newTrigger('triage').timeBased().everyMinutes(15).create();
  console.log('triage now runs every 15 minutes.');
}

function removeTrigger() {
  ScriptApp.getProjectTriggers()
    .filter((t) => t.getHandlerFunction() === 'triage')
    .forEach((t) => ScriptApp.deleteTrigger(t));
}

function ensureLabel_(cache, name) {
  if (cache[name]) return cache[name];
  const parts = name.split('/');
  let label = null;
  for (let i = 1; i <= parts.length; i++) {
    const path = parts.slice(0, i).join('/');
    label = GmailApp.getUserLabelByName(path) || GmailApp.createLabel(path);
  }
  cache[name] = label;
  return label;
}

